  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? IDOffset = _ID == null ? null
        : fbBuilder.writeString(_ID!);
    final int? SITE_IDOffset = _SITE_ID == null ? null
        : fbBuilder.writeString(_SITE_ID!);
    final int? SITE_NATIVE_IDOffset = _SITE_NATIVE_ID == null ? null
        : fbBuilder.writeString(_SITE_NATIVE_ID!);
    final int? STATION_NAMEOffset = _STATION_NAME == null ? null
        : fbBuilder.writeString(_STATION_NAME!);
    final int? STATION_IDENTITYOffset = _STATION_IDENTITY == null ? null
        : fbBuilder.writeString(_STATION_IDENTITY!);
    final int? EMISSION_DESIGNATOROffset = _EMISSION_DESIGNATOR == null ? null
        : fbBuilder.writeString(_EMISSION_DESIGNATOR!);
    final int? TIME_START_UTCOffset = _TIME_START_UTC == null ? null
        : fbBuilder.writeString(_TIME_START_UTC!);
    final int? TIME_STOP_UTCOffset = _TIME_STOP_UTC == null ? null
        : fbBuilder.writeString(_TIME_STOP_UTC!);
    final int? VALID_FROMOffset = _VALID_FROM == null ? null
        : fbBuilder.writeString(_VALID_FROM!);
    final int? VALID_UNTILOffset = _VALID_UNTIL == null ? null
        : fbBuilder.writeString(_VALID_UNTIL!);
    final int? SEASONOffset = _SEASON == null ? null
        : fbBuilder.writeString(_SEASON!);
    final int? TARGET_AREAOffset = _TARGET_AREA == null ? null
        : fbBuilder.writeString(_TARGET_AREA!);
    final int? TARGET_ZONESOffset = _TARGET_ZONES == null ? null
        : fbBuilder.writeList(_TARGET_ZONES!.map(fbBuilder.writeString).toList());
    final int? LANGUAGEOffset = _LANGUAGE == null ? null
        : fbBuilder.writeString(_LANGUAGE!);
    final int? ANTENNA_DESIGNATIONOffset = _ANTENNA_DESIGNATION == null ? null
        : fbBuilder.writeString(_ANTENNA_DESIGNATION!);
    final int? EMISSION_IDOffset = _EMISSION_ID == null ? null
        : fbBuilder.writeString(_EMISSION_ID!);
    final int? FIRST_OBSERVEDOffset = _FIRST_OBSERVED == null ? null
        : fbBuilder.writeString(_FIRST_OBSERVED!);
    final int? LAST_OBSERVEDOffset = _LAST_OBSERVED == null ? null
        : fbBuilder.writeString(_LAST_OBSERVED!);
    final int? SOURCESOffset = _SOURCES == null ? null
        : fbBuilder.writeList(_SOURCES!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    fbBuilder.startTable(34);
    fbBuilder.addOffset(0, IDOffset);
    fbBuilder.addOffset(1, SITE_IDOffset);
    fbBuilder.addOffset(2, SITE_NATIVE_IDOffset);
    fbBuilder.addOffset(3, STATION_NAMEOffset);
    fbBuilder.addOffset(4, STATION_IDENTITYOffset);
    fbBuilder.addFloat64(5, _FREQUENCY_KHZ);
    fbBuilder.addFloat64(6, _BANDWIDTH_KHZ);
    fbBuilder.addOffset(7, EMISSION_DESIGNATOROffset);
    fbBuilder.addInt8(8, _MODULATION?.value);
    fbBuilder.addInt8(9, _POLARIZATION?.value);
    fbBuilder.addInt8(10, _SERVICE?.value);
    fbBuilder.addInt8(11, _CONTENT?.value);
    fbBuilder.addOffset(12, TIME_START_UTCOffset);
    fbBuilder.addOffset(13, TIME_STOP_UTCOffset);
    fbBuilder.addUint8(14, _DAYS?.value);
    fbBuilder.addBool(15, _IRREGULAR);
    fbBuilder.addOffset(16, VALID_FROMOffset);
    fbBuilder.addOffset(17, VALID_UNTILOffset);
    fbBuilder.addOffset(18, SEASONOffset);
    fbBuilder.addOffset(19, TARGET_AREAOffset);
    fbBuilder.addOffset(20, TARGET_ZONESOffset);
    fbBuilder.addOffset(21, LANGUAGEOffset);
    fbBuilder.addFloat64(22, _TRANSMITTER_POWER_KW);
    fbBuilder.addFloat64(23, _ANTENNA_AZIMUTH_DEG);
    fbBuilder.addFloat64(24, _ANTENNA_AZIMUTH_SECONDARY_DEG);
    fbBuilder.addBool(25, _OMNIDIRECTIONAL);
    fbBuilder.addOffset(26, ANTENNA_DESIGNATIONOffset);
    fbBuilder.addOffset(27, EMISSION_IDOffset);
    fbBuilder.addInt8(28, _AUTHORITY?.value);
    fbBuilder.addInt8(29, _STATUS?.value);
    fbBuilder.addOffset(30, FIRST_OBSERVEDOffset);
    fbBuilder.addOffset(31, LAST_OBSERVEDOffset);
    fbBuilder.addUint32(32, _OBSERVATION_COUNT);
    fbBuilder.addOffset(33, SOURCESOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
